import {
  LayerType,
  createCompositionId,
  createLayerId,
  toTick,
  type IFrameState,
  type IFrameStateLayer,
} from "@motion-studio/shared";
import { describe, expect, it } from "vitest";
import { RenderingEngine } from "./rendering-engine";
import { SoftwareRenderBackend } from "./software-backend";

function makeLayer(overrides: Partial<IFrameStateLayer> = {}): IFrameStateLayer {
  return {
    layerId: createLayerId("layer-1"),
    type: LayerType.Shape,
    transform: { x: 0, y: 0, scaleX: 1, scaleY: 1, rotation: 0, anchorX: 0, anchorY: 0 },
    opacity: 1,
    zIndex: 0,
    bounds: { x: 0, y: 0, width: 4, height: 4 },
    properties: {},
    ...overrides,
  };
}

function makeFrameState(layers: IFrameStateLayer[]): IFrameState {
  return {
    tick: toTick(0),
    compositionId: createCompositionId("comp-1"),
    width: 8,
    height: 8,
    layers,
  };
}

describe("RenderingEngine", () => {
  it("has the correct engine name", () => {
    expect(new RenderingEngine(new SoftwareRenderBackend()).name).toBe("Rendering");
  });

  it("initializes the backend via setTarget", async () => {
    const backend = new SoftwareRenderBackend();
    const engine = new RenderingEngine(backend);
    await engine.setTarget({ width: 8, height: 8 });
    expect(backend.getFramebuffer()).toHaveLength(8 * 8 * 4);
  });

  it("renderFrame builds and returns the Scene Graph and draws it", async () => {
    const backend = new SoftwareRenderBackend();
    const engine = new RenderingEngine(backend);
    await engine.setTarget({ width: 8, height: 8 });

    const sceneGraph = await engine.renderFrame(makeFrameState([makeLayer()]));
    expect(sceneGraph.nodes).toHaveLength(1);
    expect(backend.getFramebuffer()[3]).toBeGreaterThan(0);
  });

  it("marks a layer dirty on the first frame and clean once unchanged", async () => {
    const engine = new RenderingEngine(new SoftwareRenderBackend());
    await engine.setTarget({ width: 8, height: 8 });
    const layerId = createLayerId("layer-1");

    await engine.renderFrame(makeFrameState([makeLayer({ layerId })]));
    expect(engine.isDirty(layerId)).toBe(true);

    await engine.renderFrame(makeFrameState([makeLayer({ layerId })]));
    expect(engine.isDirty(layerId)).toBe(false);
  });

  it("dispose() tears down the backend", async () => {
    const backend = new SoftwareRenderBackend();
    const engine = new RenderingEngine(backend);
    await engine.setTarget({ width: 8, height: 8 });
    await engine.dispose();
    expect(backend.getFramebuffer()).toHaveLength(0);
  });
});

import {
  LayerType,
  createCompositionId,
  createLayerId,
  toTick,
  type IFrameState,
  type IFrameStateLayer,
} from "@motion-studio/shared";
import { describe, expect, it } from "vitest";
import { buildSceneGraph, SceneGraphDirtyTracker } from "./scene-graph";

function makeLayer(overrides: Partial<IFrameStateLayer> = {}): IFrameStateLayer {
  return {
    layerId: createLayerId("layer-1"),
    type: LayerType.Shape,
    transform: { x: 0, y: 0, scaleX: 1, scaleY: 1, rotation: 0, anchorX: 0, anchorY: 0 },
    opacity: 1,
    zIndex: 0,
    bounds: { x: 0, y: 0, width: 100, height: 100 },
    properties: {},
    ...overrides,
  };
}

function makeFrameState(layers: IFrameStateLayer[]): IFrameState {
  return {
    tick: toTick(0),
    compositionId: createCompositionId("comp-1"),
    width: 1920,
    height: 1080,
    layers,
  };
}

describe("buildSceneGraph", () => {
  it("carries frame dimensions and flattens layers into nodes", () => {
    const layer = makeLayer();
    const sceneGraph = buildSceneGraph(makeFrameState([layer]));
    expect(sceneGraph.width).toBe(1920);
    expect(sceneGraph.height).toBe(1080);
    expect(sceneGraph.nodes).toHaveLength(1);
    expect(sceneGraph.nodes[0]).toMatchObject({ layerId: layer.layerId, type: LayerType.Shape });
  });
});

describe("SceneGraphDirtyTracker", () => {
  it("marks every node dirty on the first frame", () => {
    const tracker = new SceneGraphDirtyTracker();
    const sceneGraph = buildSceneGraph(
      makeFrameState([makeLayer({ layerId: createLayerId("a") })]),
    );
    tracker.update(sceneGraph);
    expect(tracker.graph.isDirty(createLayerId("a"))).toBe(true);
  });

  it("only marks changed nodes dirty on subsequent frames", () => {
    const tracker = new SceneGraphDirtyTracker();
    const a = createLayerId("a");
    const b = createLayerId("b");

    tracker.update(
      buildSceneGraph(makeFrameState([makeLayer({ layerId: a }), makeLayer({ layerId: b })])),
    );

    tracker.update(
      buildSceneGraph(
        makeFrameState([makeLayer({ layerId: a, opacity: 0.5 }), makeLayer({ layerId: b })]),
      ),
    );

    expect(tracker.graph.isDirty(a)).toBe(true);
    expect(tracker.graph.isDirty(b)).toBe(false);
  });

  it("marks a node dirty when a property value changes", () => {
    const tracker = new SceneGraphDirtyTracker();
    const a = createLayerId("a");
    tracker.update(
      buildSceneGraph(makeFrameState([makeLayer({ layerId: a, properties: { fill: "red" } })])),
    );
    tracker.update(
      buildSceneGraph(makeFrameState([makeLayer({ layerId: a, properties: { fill: "blue" } })])),
    );
    expect(tracker.graph.isDirty(a)).toBe(true);
  });

  it("does not mark a node dirty when nothing changed", () => {
    const tracker = new SceneGraphDirtyTracker();
    const a = createLayerId("a");
    tracker.update(buildSceneGraph(makeFrameState([makeLayer({ layerId: a })])));
    tracker.update(buildSceneGraph(makeFrameState([makeLayer({ layerId: a })])));
    expect(tracker.graph.isDirty(a)).toBe(false);
  });
});

import {
  DagCycleError,
  LayerType,
  createCompositionId,
  createLayerId,
  toTick,
} from "@motion-studio/shared";
import { describe, expect, it } from "vitest";
import { buildIdentityRenderGraph, getRenderGraphOutputNodeId, RenderGraph } from "./render-graph";
import type { ISceneGraph, ISceneGraphNode } from "./scene-graph";

function node(
  overrides: Partial<Omit<ISceneGraphNode, "layerId">> & { layerId: string },
): ISceneGraphNode {
  const { layerId, ...rest } = overrides;
  return {
    layerId: createLayerId(layerId),
    type: LayerType.Shape,
    transform: { x: 0, y: 0, scaleX: 1, scaleY: 1, rotation: 0, anchorX: 0, anchorY: 0 },
    opacity: 1,
    zIndex: 0,
    bounds: { x: 0, y: 0, width: 10, height: 10 },
    properties: {},
    ...rest,
  };
}

function sceneGraph(nodes: ISceneGraphNode[]): ISceneGraph {
  return {
    tick: toTick(0),
    compositionId: createCompositionId("comp-1"),
    width: 100,
    height: 100,
    nodes,
  };
}

describe("RenderGraph", () => {
  it("orders an effect chain dependency-first", () => {
    const graph = new RenderGraph();
    graph.addNode({ id: "source", dependencyIds: [] });
    graph.addNode({ id: "blur", dependencyIds: ["source"] });
    graph.addNode({ id: "output", dependencyIds: ["blur"] });
    expect(graph.executionOrder("output")).toEqual(["source", "blur", "output"]);
  });

  it("throws a DagCycleError for a cyclic chain", () => {
    const graph = new RenderGraph();
    graph.addNode({ id: "a", dependencyIds: ["b"] });
    graph.addNode({ id: "b", dependencyIds: ["a"] });
    expect(() => graph.executionOrder("a")).toThrow(DagCycleError);
  });
});

describe("buildIdentityRenderGraph", () => {
  it("adds one output node per Scene Graph layer", () => {
    const a = createLayerId("a");
    const b = createLayerId("b");
    const graph = buildIdentityRenderGraph(
      sceneGraph([node({ layerId: "a" }), node({ layerId: "b" })]),
    );
    expect(graph.hasNode(getRenderGraphOutputNodeId(a))).toBe(true);
    expect(graph.hasNode(getRenderGraphOutputNodeId(b))).toBe(true);
  });

  it("gives each layer's output node an empty dependency chain today (no Effects Engine yet)", () => {
    const a = createLayerId("a");
    const graph = buildIdentityRenderGraph(sceneGraph([node({ layerId: "a" })]));
    expect(graph.executionOrder(getRenderGraphOutputNodeId(a))).toEqual([
      getRenderGraphOutputNodeId(a),
    ]);
  });
});

import {
  LayerType,
  RenderBackend,
  createCompositionId,
  createLayerId,
  toTick,
} from "@motion-studio/shared";
import { describe, expect, it } from "vitest";
import { FakeWebGL2Context } from "./test-support/fake-webgl2-context";
import type { ISceneGraph, ISceneGraphNode } from "./scene-graph";
import { WebGL2RenderBackend } from "./webgl2-backend";

function node(
  overrides: Partial<Omit<ISceneGraphNode, "layerId">> & { layerId: string },
): ISceneGraphNode {
  const { layerId, ...rest } = overrides;
  return {
    layerId: createLayerId(layerId),
    type: LayerType.Shape,
    transform: { x: 0, y: 0, scaleX: 1, scaleY: 1, rotation: 0, anchorX: 0, anchorY: 0 },
    opacity: 1,
    zIndex: 0,
    bounds: { x: 0, y: 0, width: 10, height: 10 },
    properties: {},
    ...rest,
  };
}

function sceneGraph(nodes: ISceneGraphNode[]): ISceneGraph {
  return {
    tick: toTick(0),
    compositionId: createCompositionId("comp-1"),
    width: 100,
    height: 100,
    nodes,
  };
}

describe("WebGL2RenderBackend", () => {
  it("reports its kind", () => {
    expect(new WebGL2RenderBackend({ getContext: () => new FakeWebGL2Context() }).kind).toBe(
      RenderBackend.WebGL2,
    );
  });

  it("compiles and links a program during init", () => {
    const gl = new FakeWebGL2Context();
    const backend = new WebGL2RenderBackend({ getContext: () => gl });
    expect(() => backend.init({ width: 100, height: 100 })).not.toThrow();
  });

  it("issues one draw call per node, clearing once per frame", () => {
    const gl = new FakeWebGL2Context();
    const backend = new WebGL2RenderBackend({ getContext: () => gl });
    backend.init({ width: 100, height: 100 });
    backend.drawFrame(sceneGraph([node({ layerId: "a" }), node({ layerId: "b" })]));

    expect(gl.calls.filter((c) => c.op === "clear")).toHaveLength(1);
    expect(gl.calls.filter((c) => c.op === "drawArrays")).toHaveLength(2);
  });

  it("uploads each node's opacity into the color uniform's alpha channel", () => {
    const gl = new FakeWebGL2Context();
    const backend = new WebGL2RenderBackend({ getContext: () => gl });
    backend.init({ width: 100, height: 100 });
    backend.drawFrame(sceneGraph([node({ layerId: "a", opacity: 0.25 })]));

    const colorUniforms = gl.calls.filter(
      (c): c is Extract<typeof c, { op: "uniform4f" }> =>
        c.op === "uniform4f" && c.name === "u_color",
    );
    expect(colorUniforms).toHaveLength(1);
    expect(colorUniforms[0]?.w).toBe(0.25);
  });

  it("throws if drawFrame is called before init", () => {
    const backend = new WebGL2RenderBackend({ getContext: () => new FakeWebGL2Context() });
    expect(() => backend.drawFrame(sceneGraph([]))).toThrow(/init/);
  });

  it("dispose() releases the program so a later drawFrame throws", () => {
    const gl = new FakeWebGL2Context();
    const backend = new WebGL2RenderBackend({ getContext: () => gl });
    backend.init({ width: 100, height: 100 });
    backend.dispose();
    expect(() => backend.drawFrame(sceneGraph([]))).toThrow(/init/);
  });
});

