import type { AssetId } from "@motion-studio/shared";

/**
 * A resolved, drawable representation of an asset's content, attached to a
 * Scene Graph node in place of `placeholderColor` when available. Two kinds
 * because backends need genuinely different input: Canvas2D/WebGL2/WebGPU
 * can draw/upload a `CanvasImageSource` directly (`ImageBitmap` for a
 * static image, `HTMLVideoElement` for a live video frame), while the
 * Software backend has no canvas/GPU available (`05-rendering-engine/
 * canvas-fallback.md`) and instead samples a plain RGBA byte buffer.
 * `CanvasImageSource` is an ambient `lib.dom` type (already used the same
 * way in `apps/studio`'s `thumbnail-generator.ts`) — safe here since
 * `tsconfig.base.json` includes `"DOM"` in `lib`, even though this package
 * never calls DOM APIs itself; only the app layer's resolver does.
 */
export type ITextureSource =
  | {
      readonly kind: "image-source";
      readonly source: CanvasImageSource;
      readonly width: number;
      readonly height: number;
    }
  | {
      readonly kind: "raw-rgba";
      readonly pixels: Uint8ClampedArray;
      readonly width: number;
      readonly height: number;
    };

/**
 * Injected into `RenderingEngine` by the host app (`CanvasPanel`) — decode
 * itself is a browser API concern the Rendering Engine never owns (CLAUDE.md
 * engine ownership table). `resolve` must be synchronous and side-effect-free
 * from the caller's perspective (a cache read), since it runs once per Scene
 * Graph node on every rendered frame — implementations that need to decode
 * asynchronously should cache and return `undefined` on a miss, resolving in
 * the background for a later frame.
 */
export interface ITextureSourceProvider {
  resolve(assetId: AssetId): ITextureSource | undefined;
}

import { LayerType, createCompositionId, createLayerId, toTick } from "@motion-studio/shared";
import { describe, expect, it } from "vitest";
import { Canvas2DRenderBackend } from "./canvas2d-backend";
import type { ISceneGraph, ISceneGraphNode } from "./scene-graph";
import { FakeCanvas2DContext } from "./test-support/fake-canvas2d-context";

function node(
  overrides: Partial<Omit<ISceneGraphNode, "layerId">> & { layerId: string },
): ISceneGraphNode {
  const { layerId, ...rest } = overrides;
  return {
    layerId: createLayerId(layerId),
    type: LayerType.Shape,
    transform: { x: 0, y: 0, scaleX: 1, scaleY: 1, rotation: 0, anchorX: 0, anchorY: 0 },
    opacity: 1,
    zIndex: 0,
    bounds: { x: 0, y: 0, width: 10, height: 10 },
    assetId: undefined,
    texture: undefined,
    properties: {},
    ...rest,
  };
}

function sceneGraph(nodes: ISceneGraphNode[]): ISceneGraph {
  return {
    tick: toTick(0),
    compositionId: createCompositionId("comp-1"),
    width: 100,
    height: 100,
    nodes,
  };
}

describe("Canvas2DRenderBackend", () => {
  it("clears the canvas once per frame before drawing", () => {
    const ctx = new FakeCanvas2DContext();
    const backend = new Canvas2DRenderBackend({ getContext: () => ctx });
    backend.init({ width: 100, height: 100 });
    backend.drawFrame(sceneGraph([node({ layerId: "a" })]));
    expect(ctx.calls[0]).toEqual({ op: "clearRect", x: 0, y: 0, width: 100, height: 100 });
  });

  it("saves/restores the transform stack around each node", () => {
    const ctx = new FakeCanvas2DContext();
    const backend = new Canvas2DRenderBackend({ getContext: () => ctx });
    backend.init({ width: 100, height: 100 });
    backend.drawFrame(sceneGraph([node({ layerId: "a" }), node({ layerId: "b" })]));

    const saveCount = ctx.calls.filter((c) => c.op === "save").length;
    const restoreCount = ctx.calls.filter((c) => c.op === "restore").length;
    expect(saveCount).toBe(2);
    expect(restoreCount).toBe(2);
  });

  it("throws if drawFrame is called before init", () => {
    const ctx = new FakeCanvas2DContext();
    const backend = new Canvas2DRenderBackend({ getContext: () => ctx });
    expect(() => backend.drawFrame(sceneGraph([]))).toThrow(/init/);
  });

  it("draws nodes in render-queue order (lower zIndex first)", () => {
    const ctx = new FakeCanvas2DContext();
    const backend = new Canvas2DRenderBackend({ getContext: () => ctx });
    backend.init({ width: 100, height: 100 });
    backend.drawFrame(
      sceneGraph([node({ layerId: "front", zIndex: 1 }), node({ layerId: "back", zIndex: 0 })]),
    );

    const fillRectCalls = ctx.calls.filter((c) => c.op === "fillRect");
    expect(fillRectCalls).toHaveLength(2);
  });

  it("dispose() clears the held context so a later drawFrame throws", () => {
    const ctx = new FakeCanvas2DContext();
    const backend = new Canvas2DRenderBackend({ getContext: () => ctx });
    backend.init({ width: 100, height: 100 });
    backend.dispose();
    expect(() => backend.drawFrame(sceneGraph([]))).toThrow(/init/);
  });

  it("draws a resolved image-source texture via drawImage instead of the placeholder fillRect", () => {
    const ctx = new FakeCanvas2DContext();
    const backend = new Canvas2DRenderBackend({ getContext: () => ctx });
    backend.init({ width: 100, height: 100 });
    const fakeImage = {} as CanvasImageSource;
    backend.drawFrame(
      sceneGraph([
        node({
          layerId: "a",
          texture: { kind: "image-source", source: fakeImage, width: 10, height: 10 },
        }),
      ]),
    );

    expect(ctx.calls.some((c) => c.op === "fillRect")).toBe(false);
    const drawImageCalls = ctx.calls.filter((c) => c.op === "drawImage");
    expect(drawImageCalls).toEqual([
      { op: "drawImage", image: fakeImage, x: 0, y: 0, width: 10, height: 10 },
    ]);
  });
});

