  readonly VERTEX_SHADER = 35633;
  readonly FRAGMENT_SHADER = 35632;
  readonly COMPILE_STATUS = 35713;
  readonly LINK_STATUS = 35714;
  readonly ARRAY_BUFFER = 34962;
  readonly STATIC_DRAW = 35044;
  readonly TRIANGLE_STRIP = 5;
